function parseTimetable(text:string):ClassItem[]{
 const found:ClassItem[]=[]; let activeDay=1;
 const time=/\b([01]?\d|2[0-3])[:.]([0-5]\d)\s*(?:-|–|—|to)\s*([01]?\d|2[0-3])[:.]([0-5]\d)\b/i;
 for(const raw of text.split(/\n|\s{3,}/)){
  const line=raw.trim(); if(!line)continue;
  const dayIndex=days.findIndex(d=>new RegExp(`\\b${d.slice(0,3)}(?:day)?\\b`,'i').test(line)); if(dayIndex>=0)activeDay=dayIndex;
  const m=line.match(time); if(!m)continue;
  const subject=line.replace(m[0],'').replace(new RegExp(days.join('|'),'ig'),'').replace(/^[-–—|:,\s]+|[-–—|:,\s]+$/g,'')||'Class';
  found.push({id:uid(),subject:subject.slice(0,60),room:'',teacher:'',day:activeDay,start:`${m[1].padStart(2,'0')}:${m[2]}`,end:`${m[3].padStart(2,'0')}:${m[4]}`,color:colors[found.length%colors.length],enabled:true});
 }
 return found;
}
function parseGridTimetable(tokens:PdfToken[]):Record<string,ClassItem[]>{
 const result:Record<string,ClassItem[]>={};
 const dayMap:Record<string,number>={MON:1,TUES:2,WED:3,THUR:4,FRI:5,FRID:5,SAT:6,SUN:0};
 const times=new Map<number,{start:string;end:string}>();
 const timeRange=/^([01]?\d|2[0-3])[:.]([0-5]\d)\s*(?:-|–|—|to)\s*([01]?\d|2[0-3])[:.]([0-5]\d)$/i;
 for(const token of tokens){const match=token.text.match(timeRange);if(match)times.set(token.x,{start:`${match[1].padStart(2,'0')}:${match[2]}`,end:`${match[3].padStart(2,'0')}:${match[4]}`})}
 const timeTokens=tokens.filter(t=>/^\d{1,2}:\d{2}$/.test(t.text));
 for(const x of [...new Set(timeTokens.map(t=>t.x))]){const pair=timeTokens.filter(t=>Math.abs(t.x-x)<4).sort((a,b)=>b.y-a.y);if(pair.length>=2&&pair[0].text!==pair[1].text)times.set(x,{start:pair[0].text.padStart(5,'0'),end:pair[1].text.padStart(5,'0')})}
 let currentDay=1;
 for(const token of tokens){const day=dayMap[token.text.toUpperCase().replace(/DAY$/,'')];if(day!==undefined){currentDay=day;continue}const form=token.text.match(/^(Form|Class|Grade|Year)\s*([A-Za-z0-9-]+)$/i);if(!form)continue;const key=`${form[1][0].toUpperCase()+form[1].slice(1).toLowerCase()} ${form[2]}`;result[key]??=[];const subjects=tokens.filter(t=>Math.abs(t.y-token.y)<4&&t.x>token.x+20&&!/^(Form|Class|Grade|Year)/i.test(t.text)&&!/^\d{1,2}:\d{2}$/.test(t.text));for(const subject of subjects){let bestX:number|undefined,bestDistance=Infinity;for(const x of times.keys()){const d=Math.abs(x-subject.x);if(d<bestDistance){bestX=x;bestDistance=d}}if(bestX===undefined||bestDistance>32)continue;const period=times.get(bestX)!;result[key].push({id:uid(),subject:subject.text.trim(),room:key,teacher:'',day:currentDay,start:period.start,end:period.end,color:colors[result[key].length%colors.length],enabled:true})}}
 return Object.fromEntries(Object.entries(result).filter(([,items])=>items.length));
}
const normalize=(v:string)=>v.toLowerCase().replace(/\([^)]*\)/g,' ').replace(/[^a-z0-9]/g,' ').replace(/\b(the|and|of|introduction|intro|principles)\b/g,' ').replace(/\s+/g,' ').trim();
const acronym=(v:string)=>normalize(v).split(' ').filter(Boolean).map(x=>x[0]).join('');
const similarity=(a:string,b:string)=>{const na=normalize(a),nb=normalize(b);if(!na||!nb)return 0;if(na===nb)return 1;const compactA=na.replace(/\s/g,''),compactB=nb.replace(/\s/g,'');if(compactA===acronym(b)||compactB===acronym(a))return .95;const aa=new Set(na.split(' ')),bb=new Set(nb.split(' '));const common=[...aa].filter(x=>bb.has(x)||[...bb].some(y=>x.startsWith(y)||y.startsWith(x))).length;return common/Math.max(aa.size,bb.size)};
const classKey=(v:string)=>{const value=normalize(v).replace(/\b(room|rm)\b/g,' ').replace(/\s+/g,' ').trim(),match=value.match(/\b(?:form|class|grade|year)\s*([a-z0-9-]+)\b/);return match?.[1]||value};
function allocationScore(item:ClassItem,a:Allocation){
 const subjectScore=Math.max(similarity(item.subject,a.subject),...(a.aliases||[]).map(x=>similarity(item.subject,x)));
 if(!subjectScore)return 0;
 if(a.classGroup&&item.room){const itemClass=classKey(item.room),allocationClass=classKey(a.classGroup);if(itemClass&&allocationClass&&itemClass!==allocationClass)return 0;return Math.min(1,subjectScore+.08)}
 return subjectScore;
}
function applyAllocations(items:ClassItem[],allocations:Allocation[]){return items.map(c=>{let best:Allocation|undefined,score=0;for(const a of allocations){const s=allocationScore(c,a);if(s>score){best=a;score=s}}return best&&score>=.48?{...c,teacher:best.teacher,room:c.room||best.classGroup||''}:c})}
function parseAllocations(text:string):Allocation[]{const out:Allocation[]=[];for(const row of text.split('\n')){const cells=row.split(/\s{2,}|\t+|\s+(?:-|–|\|)\s+/).map(x=>x.trim()).filter(Boolean);for(let i=0;i+1<cells.length;i+=2){if(/subject|course|module/i.test(cells[i])&&/teacher|lecturer|instructor/i.test(cells[i+1]))continue;if(!/\d{1,2}[:.]\d{2}/.test(cells[i])){const codes=[...cells[i].matchAll(/\(([^)]+)\)/g)].map(m=>m[1].trim());out.push({id:uid(),subject:cells[i].replace(/\s*\([^)]+\)\s*/g,' ').trim().slice(0,80),teacher:cells[i+1].slice(0,80),aliases:codes})}}}return out}
const SUBJECT_CATALOG=[
 {name:'Agriculture',aliases:['AGRI','AGRIC']},{name:'Bible Knowledge',aliases:['B/KNOWLEDGE','B/K','BK']},{name:'Biology',aliases:['BIO']},{name:'Chemistry',aliases:['CHEM']},
 {name:'Chichewa Language',aliases:['CHICHEWA LANG','CHILA','CHICHLAN']},{name:'Chichewa Literature',aliases:['CHICHEWA LIT','CHILT','CHICHLIT']},
 {name:'English Language',aliases:['ENGLISH LANG','ENGLA','ENGLANG']},{name:'English Literature',aliases:['ENGLISH LIT','ENGLT','ENGLIT']},
 {name:'Geography',aliases:['GEOG']},{name:'History',aliases:['HIST']},{name:'Life Skills',aliases:['L/SKS','LIFESKILLS']},
 {name:'Mathematics',aliases:['MAT','MATHS']},{name:'Physics',aliases:['PHYS']},{name:'Social Studies',aliases:['SOCIAL']},
];
const subjectAliases=(subject:string)=>{const key=normalize(subject),entry=SUBJECT_CATALOG.find(item=>normalize(item.name)===key||item.aliases.some(alias=>normalize(alias)===key));return entry?[entry.name,...entry.aliases].filter(value=>normalize(value)!==key):[]};
function parseAllocationGrid(tokens:PdfToken[]):Allocation[]{
 const rows=new Map<number,PdfToken[]>();
 for(const token of tokens){const y=[...rows.keys()].find(value=>Math.abs(value-token.y)<=2)??token.y;rows.set(y,[...(rows.get(y)||[]),token])}
 const out:Allocation[]=[];
 for(const row of rows.values()){
  const ordered=[...row].sort((a,b)=>a.x-b.x),teachers=ordered.filter(t=>/^(mr|mrs|miss|ms)\.?\s/i.test(t.text));
  if(!teachers.length)continue;
  const subject=ordered.find(t=>t.x<teachers[0].x&&!/allocation|subject|form/i.test(t.text))?.text.trim();
  if(!subject)continue;
  teachers.forEach((teacher,index)=>out.push({id:uid(),subject,teacher:teacher.text.trim(),aliases:subjectAliases(subject),classGroup:`Form ${index+1}`}));
 }
 return out;
}
async function parseDocxAllocation(file:File):Promise<Record<string,Allocation[]>>{const zip=await JSZip.loadAsync(await file.arrayBuffer());const xml=await zip.file('word/document.xml')?.async('string');if(!xml)return{};const doc=new DOMParser().parseFromString(xml,'application/xml');const rows=[...doc.getElementsByTagNameNS('*','tr')];const cellText=(cell:Element)=>[...cell.getElementsByTagNameNS('*','t')].map(n=>n.textContent||'').join('').replace(/\s+/g,' ').trim();const table=rows.map(r=>[...r.getElementsByTagNameNS('*','tc')].map(cellText)).filter(r=>r.length>1),group=/^(form|class|grade|year)\s*[a-z0-9-]+$/i;const headerIndex=table.findIndex(r=>r.some(c=>group.test(c)));if(headerIndex<0)return{};const headers=table[headerIndex],result:Record<string,Allocation[]>={};headers.forEach(h=>{if(group.test(h))result[h.replace(/\s+/g,' ')]=[]});for(const row of table.slice(headerIndex+1)){const subject=row[0]?.trim();if(!subject)continue;headers.forEach((h,i)=>{const key=h.replace(/\s+/g,' '),teacher=row[i]?.trim();if(result[key]&&teacher)result[key].push({id:uid(),subject,teacher,aliases:subjectAliases(subject)})})}return result}
const teacherKey=(v:string)=>v.toLowerCase().replace(/\b(mr|mrs|miss|ms)\b/g,'').replace(/[^a-z]/g,'');
const overlaps=(a:ClassItem,b:ClassItem)=>a.day===b.day&&a.id!==b.id&&a.start<b.end&&b.start<a.end;
const nextDate=(day:number,time:string,lead:number)=>{const now=new Date(),d=new Date();const [h,m]=time.split(':').map(Number);d.setHours(h,m-lead,0,0);d.setDate(d.getDate()+((day-d.getDay()+7)%7));if(d<=now)d.setDate(d.getDate()+7);return d};
const notificationId=(value:string)=>{let hash=0;for(const char of value)hash=(hash*31+char.charCodeAt(0))&0x7fffffff;return 100+(hash%2000000000)};

