 const importAllocationPdf=async(e:React.ChangeEvent<HTMLInputElement>)=>{const f=e.target.files?.[0];if(!f)return;setBusy(true);try{let found:Allocation[]=[];if(f.name.toLowerCase().endsWith('.docx')){const forms=await parseDocxAllocation(f);found=Object.entries(forms).flatMap(([classGroup,items])=>items.map(a=>({...a,classGroup})))}else{const content=await pdfContent(f);found=parseAllocationGrid(content.tokens);if(!found.length)found=parseAllocations(content.text)}if(!found.length){notify('No allocations found','No subject–teacher pairs were detected. You can enter them manually below.');return}found=[...new Map(found.map(a=>[`${normalize(a.classGroup||'all')}:${normalize(a.subject)}:${teacherKey(a.teacher)}`,a])).values()];const rematch=(items:ClassItem[])=>applyAllocations(items.map(c=>({...c,teacher:''})),found);const matched=rematch(classes);setAllocations(found);setClasses(matched);setTimetables(current=>current.map(t=>({...t,classes:t.id===activeId?matched:rematch(t.classes),allocations:found})));const names=[...new Map(found.map(a=>[teacherKey(a.teacher),a.teacher])).values()];if(names.length)setTeacherChoices(names);else notify('Allocation imported',`${found.length} subject and class matches were saved for every timetable.`);}catch{notify('Could not read allocations','That allocation file could not be read. Use a PDF or Word .docx file.')}finally{setBusy(false);e.target.value=''}};
 const add=()=>{if(!draft.subject)return;const item:ClassItem={id:uid(),subject:draft.subject,room:draft.room||'',teacher:draft.teacher||'',day:Number(draft.day||1),start:draft.start||'08:00',end:draft.end||'09:00',color:colors[classes.length%colors.length],enabled:true};const next=applyAllocations([...classes,item],allocations);if(!activeId){const id=uid(),table:Timetable={id,name:'Timetable 1',classes:next,file:null,createdAt:Date.now(),allocations,teacherName:settings.teacherName,classGroup:settings.classGroup,scheduleFilter:settings.scheduleFilter,remindersEnabled:true};setActiveId(id);setTimetables([table]);scheduleAll(next,settings,table)}else scheduleAll(next);setClasses(next);setShowAdd(false);setDraft({day:1,start:'08:00',end:'09:00'})};
