function SchedulePicker({schedules,choose,close}:{schedules:Record<string,ClassItem[]>;choose:(items:ClassItem[],name:string)=>void;close:()=>void}){const names=Object.keys(schedules),[selected,setSelected]=useState<string[]>(names),[preview,setPreview]=useState(names[0]||'');const toggle=(name:string)=>setSelected(current=>current.includes(name)?current.filter(x=>x!==name):[...current,name]);const finish=()=>choose(selected.flatMap(name=>schedules[name]),selected.join(', '));const chosen=selected.flatMap(name=>schedules[name]),uncertain=chosen.filter(c=>!c.subject||c.subject==='Class'||!c.room||!c.start||!c.end);return <div className="scrim"><div className="modal picker importReview" role="dialog" aria-modal="true"><button className="close" onClick={close}><X/></button><small>IMPORT REVIEW</small><h2>Confirm detected timetable</h2><p>All detected forms are selected so the complete master timetable is imported. Deselect a form only when you intentionally want to exclude it.</p><div className="reviewStats"><span><b>{chosen.length}</b><small>periods selected</small></span><span><b>{selected.length}/{names.length}</b><small>forms selected</small></span><span className={uncertain.length?'warn':''}><b>{uncertain.length}</b><small>need review</small></span></div><div className="toolButtons"><button onClick={()=>setSelected(names)}>Select all forms</button><button disabled={!selected.length} onClick={()=>setSelected([])}>Clear selection</button></div><div className="formChoices multiFormChoices">{Object.entries(schedules).map(([name,items])=><button className={selected.includes(name)?'selected':''} key={name} onClick={()=>{toggle(name);setPreview(name)}} aria-pressed={selected.includes(name)}><span className="checkBox">{selected.includes(name)?<CheckCircle2/>:null}</span><b>{name}</b><span>{items.length} periods</span></button>)}</div>{preview&&<details className="compactDetails" open={names.length===1}><summary><span><b>Detected entries</b><small>{preview}</small></span><ChevronRight/></summary><div className="detailsList reviewEntries">{schedules[preview].slice(0,40).map(c=><div key={c.id}><b>{days[c.day]} {c.start}–{c.end}</b><small>{c.room||'Class needs confirmation'} • {c.subject||'Subject needs confirmation'}</small></div>)}</div></details>}<button className="primary selectionDone" disabled={!selected.length} onClick={finish}>Confirm and import complete timetable ({chosen.length} periods)</button></div></div>}
